import subprocess
def cell(cover, compare_prev=None):
    evs=[ev("pass","pkg/a","TestX",elapsed=0.01)]
    if cover is not None: evs.append(ev("output","pkg/a",None,f"coverage: {cover}% of statements\n"))
    evs.append(ev("pass","pkg/a",None,elapsed=1))
    write(evs,"/tmp/curr.json")
