{"command":"cat > width.go <<'GO'
package main

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// ANSI escape sequence parsing helpers.
// parseANSI returns the length in bytes of an ANSI escape sequence at the
// start of s, or 0 if s does not start with one.
func parseANSI(s string) int {
	if len(s) < 2 || s[0] != 0x1b {
		return 0
	}
	switch s[1] {
	case '[': // CSI: ESC [ params ... final byte 0x40-0x7e
		for i := 2; i < len(s); i++ {
			c := s[i]
			if c >= 0x40 && c <= 0x7e {
				return i + 1
			}
		}
		return len(s)
	case ']': // OSC: ESC ] ... terminated by BEL or ESC backslash
		for i := 2; i < len(s); i++ {
			if s[i] == 0x07 {
				return i + 1
			}
			if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '\\' {
				return i + 2
			}
		}
		return len(s)
	case 'P', 'X', '^', '_': // DCS etc - terminated by ST (ESC \)
		for i := 2; i < len(s); i++ {
			if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '\\' {
				return i + 2
			}
		}
		return len(s)
	default:
		// ESC followed by a single character.
		return 2
	}
}

func runeDisplayWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 0x20 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	if r == 0x200b || r == 0x200c || r == 0x200d || r == 0xfeff {
		return 0
	}
	if unicode.In(r, unicode.Mn, unicode.Me, unicode.Cc, unicode.Cf) {
		// combining marks etc.
		if r < 0x300 {
			// some Cf already handled, keep simple
		} else {
			return 0
		}
		return 0
	}
	if isWideRune(r) {
		return 2
	}
	return 1
}

func isWideRune(r rune) bool {
	// East Asian Wide / Fullwidth and common emoji ranges.
	switch {
	case r >= 0x1100 && r <= 0x115f, // Hangul Jamo
		r >= 0x2e80 && r <= 0x303e,
		r >= 0x3041 && r <= 0x33ff,
		r >= 0x3400 && r <= 0x4dbf,
		r >= 0x4e00 && r <= 0x9fff,
		r >= 0xa000 && r <= 0xa4cf,
		r >= 0xac00 && r <= 0xd7a3,
		r >= 0xf900 && r <= 0xfaff,
		r >= 0xfe10 && r <= 0xfe19,
