{"command":"cat > wrap.go <<'GO'
package main

import (
	"strings"
	"unicode/utf8"
)

type wrapElem struct {
	s string
	w int
}

type wrapToken struct {
	kind  int // 0 word, 1 spaces, 2 newline
	raw   string
	width int
	elems []wrapElem
}

func tokenizeWrap(s string) []wrapToken {
	var toks []wrapToken
	i := 0
	for i < len(s) {
		if s[i] == '\n' {
			toks = append(toks, wrapToken{kind: 2, raw: "\n"})
			i++
			continue
		}
		if s[i] == ' ' {
			j := i
			for j < len(s) && s[j] == ' ' {
				j++
			}
			raw := s[i:j]
			toks = append(toks, wrapToken{kind: 1, raw: raw, width: len(raw)})
			i = j
			continue
		}
		// word fragment
		start := i
		var elems []wrapElem
		width := 0
		for i < len(s) {
			if n := parseANSI(s[i:]); n > 0 {
				elems = append(elems, wrapElem{s: s[i : i+n], w: 0})
				i += n
				continue
			}
			if s[i] == ' ' || s[i] == '\n' {
				break
			}
			r, size := utf8.DecodeRuneInString(s[i:])
			if r == utf8.RuneError && size == 1 {
				elems = append(elems, wrapElem{s: s[i : i+1], w: 1})
				width++
				i++
				continue
			}
			elems = append(elems, wrapElem{s: s[i : i+size], w: runeDisplayWidth(r)})
			width += runeDisplayWidth(r)
			i += size
			if r == '-' {
				break
			}
		}
		toks = append(toks, wrapToken{kind: 0, raw: s[start:i], width: width, elems: elems})
	}
	return toks
}

type ansiState struct {
	params []string
}

func (a *ansiState) feed(s string) {
	for len(s) > 0 {
		n := parseANSI(s)
		if n == 0 {
			_, size := utf8.DecodeRuneInString(s)
			if size <= 0 {
				size = 1
			}
			s = s[size:]
			continue
		}
		seq := s[:n]
		s = s[n:]
		if len(seq) >= 3 && seq[1] == '[' && seq[len(seq)-1] == 'm' {
			params := seq[2 : len(seq)-1]
			if params == "" {
				a.params = nil
				continue
			}
			for _, p := range strings.Split(params, ";") {
				if p == "0" || p == "" {
					a.params = nil
					continue
				}
				a.params = append(a.params, p)
			}
		}
	}
}
func (a *ansiState) active() bool { return len(a.params) > 0 }
func (a *ansiState) reopen() string {
	if !a.active() {
		return ""
	}
	return "\x1b[" + strings.Join(a.params, ";") + "m"
}

// wrapText word-wraps s to width display columns, in a manner compatible
// with the wrapping used for panic output. Tabs must already have been
// expanded by the caller.
