{"command":"cat > render.go <<'GO'
package main

import (
	"fmt"
	"io"
	"sort"
	"strings"

	"tparse/parse"
)

type options struct {
	help, version                     bool
	all, pass, skip, notests          bool
	smallscreen                       bool
	slow                              int
	sortBy                            string
	nocolor                           bool
	format                            string
	file                              string
	follow                            bool
	followOutput                      string
	includeTimestamp                  bool
	progress                          bool
	compare                           string
	trimpath                          string
	// effective values
	colorEnabled bool // nocolor/NO_COLOR resolved (emoji in markdown)
	termWidth    int
}

func (o *options) showPass() bool { return o.all || o.pass }
func (o *options) showSkip() bool { return o.all || o.skip }

// statusText formats a status for tables / progress.
func (o *options) formatStatus(status string) string {
	if status == "" {
		return ""
	}
	if o.format == "markdown" {
		if !o.colorEnabled {
			return status
		}
		var emoji string
		switch status {
		case "PASS":
			emoji = "🟢"
		case "SKIP", "NOTEST":
			emoji = "🟡"
		case "FAIL", "PANIC":
			emoji = "🔴"
		default:
			return status
		}
		return emoji + " " + status
	}
	if !o.colorEnabled {
		return status
	}
	var code string
	switch status {
	case "PASS":
		code = "92"
	case "SKIP", "NOTEST":
		code = "93"
	case "FAIL", "PANIC":
		code = "91"
	default:
		return status
	}
	return "\x1b[" + code + "m" + status + "\x1b[0m"
}

func (o *options) color103(s string) string {
	if !o.colorEnabled || o.format == "markdown" {
		return s
	}
	return "\x1b[38;5;103m" + s + "\x1b[0m"
}
func (o *options) doubleRed(s string) string {
	if !o.colorEnabled || o.format == "markdown" {
		return s
	}
	return "\x1b[91m\x1b[91m" + s + "\x1b[0m\x1b[0m"
}
func (o *options) faintEmpty() string {
	if !o.colorEnabled || o.format == "markdown" {
		return ""
	}
	return "\x1b[2m\x1b[0m"
}

// displayPackage applies trimpath and smallscreen to a package name
// for use in tables.
func (o *options) displayPackage(name string) string {
	s := strings.TrimPrefix(name, o.trimpath)
	if o.smallscreen {
		if idx := strings.LastIndex(s, "/"); idx >= 0 {
			s = s[idx+1:]
		}
	}
	return s
}

// formatTestName applies smallscreen splitting.
func (o *options) formatTestName(name string) string {
	if !o.smallscreen || len(name) <= 32 {
		return name
	}
	parts := strings.Split(name, "/")
	if len(parts) <= 1 {
		return name
	}
	var b strings.Builder
	b.WriteString(parts[0])
	for _, part := range parts[1:] {
		// chunk part into 30-byte pieces
		if part == "" {
			b.WriteString("\n /")
			continue
		}
		chunks := []string{}
		for i := 0; i < len(part); i += 30 {
			end := i + 30
			if end > len(part) {
				end = len(part)
			}
			chunks = append(chunks, part[i:end])
		}
		for j, ch := range chunks {
			if j == 0 {
				b.WriteString("\n /")
			} else {
				b.WriteString("\n  ")
			}
			b.WriteString(ch)
			if j < len(chunks)-1 {
				b.WriteString(" …")
			}
		}
	}
	return b.String()
}

// ---- tables ----

const (
	alignLeft = iota
	alignCenter
)

func alignPad(s string, width, align int) string {
	w := visibleWidth(s)
	if w >= width {
		return s
	}
	pad := width - w
	if align == alignCenter {
		left := pad / 2
		right := pad - left
		return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
	}
	return s + strings.Repeat(" ", pad)
}

// renderTable renders headers+rows in o.format to w.
func (o *options) renderTable(w io.Writer, headers []string, aligns []int, rows [][]string) {
	n := len(headers)
	widths := make([]int, n)
	for i, h := range headers {
		widths[i] = visibleWidth(h)
	}
	// split rows into physical lines for width calc
	type prow [][]string // per row: per cell: lines
	prows := make([]prow, len(rows))
	for ri, row := range rows {
		pr := make([][]string, n)
		for ci := 0; ci < n; ci++ {
			cell := ""
			if ci < len(row) {
				cell = row[ci]
			}
			lines := strings.Split(cell, "\n")
			pr[ci] = lines
			for _, l := range lines {
				if vw := visibleWidth(l); vw > widths[ci] {
					widths[ci] = vw
				}
			}
		}
		prows[ri] = pr
	}
	segs := make([]int, n) // segment length incl padding spaces
	total := n + 1
	for i := range widths {
		segs[i] = widths[i] + 2
		total += segs[i]
	}
	segStr := func(cellLine string, ci int, isHeader bool) string {
		al := aligns[ci]
		if isHeader {
			al = alignCenter
		}
		return " " + alignPad(cellLine, widths[ci], al) + " "
	}
	lineFor := func(cells []string, isHeader bool) string {
		parts := make([]string, n)
		for i := range cells {
			parts[i] = segStr(cells[i], i, isHeader)
		}
		switch o.format {
		case "markdown":
			return "|" + strings.Join(parts, "|") + "|\n"
		case "plain":
			return " " + strings.Join(parts, " ") + " \n"
		default:
			return "│" + strings.Join(parts, "│") + "│\n"
		}
	}
	border := func(left, mid, right string, fill string) string {
		parts := make([]string, n)
		for i := range segs {
			parts[i] = strings.Repeat(fill, segs[i])
		}
		return left + strings.Join(parts, mid) + right + "\n"
	}
	switch o.format {
	case "markdown":
		fmt.Fprint(w, lineFor(headers, true))
		parts := make([]string, n)
		for i := range segs {
			parts[i] = strings.Repeat("-", segs[i])
		}
		fmt.Fprint(w, "|"+strings.Join(parts, "|")+"|\n")
	case "plain":
		fmt.Fprint(w, lineFor(headers, true))
		fmt.Fprint(w, strings.Repeat(" ", total)+"\n")
	default:
		fmt.Fprint(w, border("╭", "┬", "╮", "─"))
		fmt.Fprint(w, lineFor(headers, true))
		fmt.Fprint(w, border("├", "┼", "┤", "─"))
	}
	for _, pr := range prows {
		height := 1
		for _, lines := range pr {
			if len(lines) > height {
				height = len(lines)
			}
		}
		for li := 0; li < height; li++ {
			cells := make([]string, n)
			for ci := range pr {
				if li < len(pr[ci]) {
					cells[ci] = pr[ci][li]
				}
			}
			fmt.Fprint(w, lineFor(cells, false))
		}
	}
	if o.format == "basic" {
		fmt.Fprint(w, border("╰", "┴", "╯", "─"))
	}
}

// sortedPackages builds the package slice (from the map) and sorts it.
func sortedPackages(p *parse.Parser, sortBy string) []*parse.Package {
	pkgs := make([]*parse.Package, 0, len(p.Packages))
	for _, pkg := range p.Packages {
		pkgs = append(pkgs, pkg)
	}
	sort.Slice(pkgs, func(i, j int) bool {
		switch sortBy {
		case "elapsed":
			return pkgs[i].Elapsed > pkgs[j].Elapsed
		case "cover":
			return pkgs[i].Cover > pkgs[j].Cover
		default:
			return pkgs[i].Name < pkgs[j].Name
		}
	})
	return pkgs
}

// test rows for a single package (basic/plain form, 4 cols if withPkg else 3)
func (o *options) packageTestRows(pkg *parse.Package, withPkg bool) [][]string {
	var passed, skipped, failed []*parse.Test
	for _, t := range pkg.Tests {
		switch t.Status() {
		case "PASS":
			passed = append(passed, t)
		case "SKIP":
			skipped = append(skipped, t)
		default:
			failed = append(failed, t)
		}
	}
	sort.Slice(passed, func(i, j int) bool { return passed[i].Elapsed > passed[j].Elapsed })
	if o.slow > 0 && len(passed) > o.slow {
		passed = passed[:o.slow]
	}
	var rows [][]string
	add := func(list []*parse.Test) {
		for _, t := range list {
			row := []string{o.formatStatus(t.Status()), fmt.Sprintf("%.2f", t.Elapsed), o.formatTestName(t.Name)}
			if withPkg {
				row = append(row, o.displayPackage(t.Package))
			}
			rows = append(rows, row)
		}
	}
	if o.showPass() {
		add(passed)
	}
	if o.showSkip() {
		add(skipped)
	}
	add(failed)
	return rows
}

// printTestTables prints the aggregated (basic/plain) or per-package (markdown) test tables.
func (o *options) printTestTables(w io.Writer, pkgs []*parse.Package) {
	if !o.showPass() && !o.showSkip() {
		return
	}
	if o.format == "markdown" {
		for _, pkg := range pkgs {
			if pkg.Panicked || pkg.NoTestReason != "" {
				continue
			}
			rows := o.packageTestRows(pkg, false)
			if len(rows) == 0 {
				fmt.Fprintln(w)
				continue
			}
			pass, fail, skip := pkg.Counts()
			fmt.Fprintf(w, "## 📦 Package **`%s`**\n\n", pkg.Name)
			fmt.Fprintf(w, "Tests: ✓ %d passed | %d skipped | %d failed\n", pass, skip, fail)
			if o.slow > 0 && pass > o.slow {
				fmt.Fprintf(w, "↓ Slowest %d passed tests shown (of %d)\n", o.slow, pass)
			}
			fmt.Fprintf(w, "\n<details>\n\n<summary>Click for test summary</summary>\n\n")
			o.renderTable(w, []string{"Status", "Elapsed", "Test"}, []int{alignCenter, alignCenter, alignLeft}, rows)
			fmt.Fprintf(w, "</details>\n\n\n")
		}
		return
	}
	var rows [][]string
	for i, pkg := range pkgs {
		if pkg.Panicked || pkg.NoTestReason != "" {
			continue
		}
		rows = append(rows, o.packageTestRows(pkg, true)...)
		if i < len(pkgs)-1 {
			rows = append(rows, []string{"", "", "", ""})
		}
	}
	if len(rows) > 0 {
		o.renderTable(w, []string{"Status", "Elapsed", "Test", "Package"}, []int{alignCenter, alignCenter, alignLeft, alignLeft}, rows)
	}
}

// ---- failure / panic sections ----

func (o *options) box(status, name, suffix string) [3]string {
	visible := "   " + status + "  package: " + name + suffix + "   "
	width := visibleWidth(visible)
	top := o.color103("┏" + strings.Repeat("━", width) + "┓")
	mid := o.color103("┃") + "   " + o.doubleRed(status) + "  package: " + name + suffix + "   " + o.color103("┃")
	bot := o.color103("┗" + strings.Repeat("━", width) + "┛")
	return [3]string{top, mid, bot}
}

func (o *options) formatFailLine(failLine string) string {
	if failLine == "" {
		return ""
	}
	if o.format == "markdown" {
		return failLine
	}
	lines := strings.Split(failLine, "\n")
	maxW := 0
	for _, l := range lines {
		if vw := visibleWidth(l); vw > maxW {
			maxW = vw
		}
	}
	for i, l := range lines {
		out := l
		if o.colorEnabled {
			out = "\x1b[31m" + l + "\x1b[0m"
		}
		if pad := maxW - visibleWidth(l); pad > 0 {
			out += strings.Repeat(" ", pad)
		}
		lines[i] = out
	}
	return strings.Join(lines, "\n")
}

type failGroup struct {
	key   string
	tests []*parse.Test
}

func failedGroups(pkg *parse.Package) []failGroup {
	m := make(map[string][]*parse.Test)
	for _, t := range pkg.Tests {
		if t.Status() != "FAIL" {
			continue
		}
		key := strings.Split(t.Name, "/")[0]
		m[key] = append(m[key], t)
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	groups := make([]failGroup, 0, len(keys))
	for _, k := range keys {
		tests := m[k]
		sort.Slice(tests, func(i, j int) bool { return tests[i].Name < tests[j].Name })
		groups = append(groups, failGroup{key: k, tests: tests})
	}
	return groups
}

func hasFailed(pkg *parse.Package) bool {
	for _, t := range pkg.Tests {
		if t.Status() == "FAIL" {
			return true
		}
	}
	return false
}

func (o *options) printFailureContent(w io.Writer, pkg *parse.Package) {
	groups := failedGroups(pkg)
	for gi, g := range groups {
		if gi > 0 {
			fmt.Fprintln(w, strings.Repeat("─", o.termWidth))
			// separator blank line: faint empty + spaces
			fmt.Fprintln(w, o.faintEmpty()+strings.Repeat(" ", o.termWidth))
		}
		for _, t := range g.tests {
			fmt.Fprintln(w, o.formatFailLine(t.FailLine))
			if t.Body != "" {
				fmt.Fprintln(w)
				fmt.Fprintln(w, t.Body)
			}
		}
	}
}

func (o *options) printFailuresAndPanics(w io.Writer, pkgs []*parse.Package) {
	for _, pkg := range pkgs {
		if pkg.Panicked {
			o.printPanic(w, pkg)
			continue
		}
		if !hasFailed(pkg) {
			continue
		}
		status := strings.ToUpper(string(pkg.Action))
		if o.format == "markdown" {
			emoji := ""
			if o.colorEnabled {
				emoji = "🔴 "
			}
			fmt.Fprintf(w, "## %s%s • %s\n\n", emoji, status, pkg.Name)
			fmt.Fprintln(w, "```")
			o.printFailureContent(w, pkg)
			fmt.Fprintln(w, "```")
			fmt.Fprintln(w)
		} else {
			box := o.box(status, pkg.Name, "")
			fmt.Fprintln(w, box[0])
			fmt.Fprintln(w, box[1])
			fmt.Fprintln(w, box[2])
			fmt.Fprintln(w)
			o.printFailureContent(w, pkg)
		}
	}
}

func (o *options) printPanic(w io.Writer, pkg *parse.Package) {
	var header string
	if o.format == "markdown" {
		emoji := ""
		if o.colorEnabled {
			emoji = "🔴 "
		}
		header = "## " + emoji + "PANIC • " + pkg.Name
		if pkg.PanicTest != "" {
			header += " • " + pkg.PanicTest
		}
	} else {
		suffix := ""
		if pkg.PanicTest != "" {
			suffix = " • " + pkg.PanicTest
		}
		box := o.box("PANIC", pkg.Name, suffix)
		header = box[0] + "\n" + box[1] + "\n" + box[2]
	}
	body := strings.ReplaceAll(pkg.PanicOutput, "\t", "    ")
	wrapped := wrapText(body, o.termWidth)
	block := header + "\n" + wrapped
	padded := padBlock(block, o.termWidth)
	fmt.Fprintln(w, padded)
}

// ---- summary ----

func (o *options) coverText(pkg *parse.Package, comparePkgs map[string]*parse.Package, compareLoaded bool) string {
	if !pkg.HasCover {
		return "--"
	}
	text := fmt.Sprintf("%.1f%%", pkg.Cover)
	if compareLoaded {
		prev, ok := findComparePackage(pkg, comparePkgs)
		if !ok {
			text = fmt.Sprintf("%.1f%% (-)", pkg.Cover)
		} else {
			delta := pkg.Cover - prev.Cover
			sign := ""
			if delta > 0 {
				sign = "+"
			}
			text = fmt.Sprintf("%.1f%% (%s%.1f%%)", pkg.Cover, sign, delta)
		}
	}
	if o.colorEnabled && o.format != "markdown" && pkg.Cover != 0 {
		var code string
		switch {
		case pkg.Cover <= 50:
			code = "91"
		case pkg.Cover < 80:
			code = "93"
		default:
			code = "92"
		}
		text = "\x1b[" + code + "m" + text + "\x1b[0m"
	}
	return text
}

func findComparePackage(pkg *parse.Package, comparePkgs map[string]*parse.Package) (*parse.Package, bool) {
	if comparePkgs == nil {
		return nil, false
	}
	// Packages in the compare parser are keyed by their event package
	// string. The current package is most reliably identified by its
	// display name when set; fall back to key matching by scanning for
	// a package whose name matches.
	// First try direct key lookup by Name, then by Key, then scan by Name.
	if p, ok := comparePkgs[pkg.Name]; ok && pkg.Name != "" {
		return p, true
	}
	if p, ok := comparePkgs[pkg.Key]; ok {
		// Only accept a key match if the previous package's name is
		// also that key or empty-but-keyed case is ambiguous; to match
		// observed behaviour for named packages this is the usual path.
		// Determine acceptance: if current package has a terminal name,
		// Key == Name normally, so above already handled. For unnamed
		// current packages, original appears to look up by Name
		// (empty), so do not accept key match when Name is empty.
		if pkg.Name != "" {
			return p, true
		}
	}
	return nil, false
}

func (o *options) elapsedText(pkg *parse.Package) string {
	if pkg.Cached {
		return "(cached)"
	}
	return fmt.Sprintf("%.2fs", pkg.Elapsed)
}

// isZeroCoverNoTests reports packages excluded from the summary list:
// an explicit 0.0% coverage, no tests, not panic and not a notest package.
func isZeroCoverNoTests(pkg *parse.Package) bool {
	return !pkg.Panicked && pkg.NoTestReason == "" && pkg.HasCover && pkg.Cover == 0 && len(pkg.Tests) == 0
}

// printSummary prints the summary table and returns a compare warning
// message to print (to stderr) afterwards, or "".
func (o *options) printSummary(w io.Writer, pkgs []*parse.Package, comparePkgs map[string]*parse.Package, compareLoaded bool) {
	// Build candidate list (all non-panic packages except zero-cover/no-test)
	var candidates []*parse.Package
	var panics []*parse.Package
	for _, pkg := range pkgs {
		if pkg.Panicked {
			panics = append(panics, pkg)
			continue
		}
		if isZeroCoverNoTests(pkg) {
			continue
		}
		candidates = append(candidates, pkg)
	}
	if len(candidates) == 0 && len(panics) == 0 {
		return
	}
	showNoTests := o.notests || len(candidates) == 1
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	aligns := []int{alignCenter, alignCenter, alignLeft, alignCenter, alignCenter, alignCenter, alignCenter}
	var rows [][]string
	for _, pkg := range panics {
		rows = append(rows, []string{o.formatStatus("PANIC"), o.elapsedText(pkg), o.displayPackage(pkg.Name), "--", "--", "--", "--"})
	}
	// regular first
	for _, pkg := range candidates {
		if pkg.NoTestReason != "" {
			continue
		}
		pass, fail, skip := pkg.Counts()
		status := strings.ToUpper(string(pkg.Action))
		rows = append(rows, []string{
			o.formatStatus(status),
			o.elapsedText(pkg),
			o.displayPackage(pkg.Name),
			o.coverText(pkg, comparePkgs, compareLoaded),
			fmt.Sprintf("%d", pass),
			fmt.Sprintf("%d", fail),
			fmt.Sprintf("%d", skip),
		})
	}
	if showNoTests {
		for _, pkg := range candidates {
			if pkg.NoTestReason == "" {
				continue
			}
			rows = append(rows, []string{
				o.formatStatus("NOTEST"),
				o.elapsedText(pkg),
				o.displayPackage(pkg.Name) + "\n" + pkg.NoTestReason,
				"--", "--", "--", "--",
			})
		}
	}
	o.renderTable(w, headers, aligns, rows)
}
GO
"}

