	"    go test ./... -json | tparse [options...]\n" +
	"    go test [packages...] -json | tparse [options...]\n" +
	"    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out\n" +
	"\n" +
	"Options:\n" +
	"    -h                 Show help.\n" +
	"    -v                 Show version.\n" +
	"    -all               Display table event for pass and skip. (Failed items always displayed)\n" +
	"    -pass              Display table for passed tests.\n" +
	"    -skip              Display table for skipped tests.\n" +
	"    -notests           Display packages containing no test files or empty test files.\n" +
	"    -smallscreen       Split subtest names vertically to fit on smaller screens.\n" +
	"    -slow              Number of slowest tests to display. Default is 0, display all.\n" +
	"    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.\n" +
	"    -nocolor           Disable all colors. (NO_COLOR also supported)\n" +
	"    -format            The output format for tables [basic, plain, markdown]. Default is basic.\n" +
	"    -file              Read test output from a file.\n" +
	"    -follow            Follow raw output from go test to stdout.\n" +
	"    -follow-output     Write raw output from go test to a file (takes precedence over -follow).\n" +
	"    -include-timestamp Include timestamps in follow output. \n" +
	"    -progress          Print a single summary line for each package. Useful for long running test suites.\n" +
	"    -compare           Compare against a previous test output file. (experimental)\n" +
	"    -trimpath          Remove path prefix from package names in output, simplifying their display.\n"

func termWidth() int {
	type winsize struct {
		Row, Col, X, Y uint16
	}
	ws := &winsize{}
	r, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if r != 0 || errno != 0 {
		return 96
	}
	return int(ws.Col)
}

func main() {
	var o options
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}
	fs.BoolVar(&o.help, "h", false, "")
	fs.BoolVar(&o.help, "help", false, "")
	fs.BoolVar(&o.version, "v", false, "")
	fs.BoolVar(&o.version, "version", false, "")
	fs.BoolVar(&o.all, "all", false, "")
	fs.BoolVar(&o.pass, "pass", false, "")
	fs.BoolVar(&o.skip, "skip", false, "")
	fs.BoolVar(&o.notests, "notests", false, "")
	fs.BoolVar(&o.smallscreen, "smallscreen", false, "")
	fs.IntVar(&o.slow, "slow", 0, "")
	fs.StringVar(&o.sortBy, "sort", "name", "")
	fs.BoolVar(&o.nocolor, "nocolor", false, "")
	fs.StringVar(&o.format, "format", "basic", "")
	fs.StringVar(&o.file, "file", "", "")
	fs.BoolVar(&o.follow, "follow", false, "")
	fs.StringVar(&o.followOutput, "follow-output", "", "")
	fs.BoolVar(&o.includeTimestamp, "include-timestamp", false, "")
	fs.BoolVar(&o.progress, "progress", false, "")
	fs.StringVar(&o.compare, "compare", "", "")
	fs.StringVar(&o.trimpath, "trimpath", "", "")
	if err := fs.Parse(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		fmt.Fprint(os.Stderr, usageText)
		os.Exit(2)
	}
	if o.version {
		fmt.Println("tparse version: (devel)")
		return
	}
	if o.help {
		fmt.Fprint(os.Stdout, usageText)
		return
	}
	if err := run(&o); err != nil {
		fmt.Fprintln(os.Stderr, err)
	}
}

func run(o *options) error {
	if o.format != "basic" && o.format != "plain" && o.format != "markdown" {
		return fmt.Errorf("invalid option:%q. The -format flag must be one of: basic, plain or markdown", o.format)
	}
	if o.sortBy != "name" && o.sortBy != "elapsed" && o.sortBy != "cover" {
		return fmt.Errorf("invalid option:%q. The -sort flag must be one of: name, elapsed or cover", o.sortBy)
	}
	_, noColorEnv := os.LookupEnv("NO_COLOR")
	o.colorEnabled = !o.nocolor && !noColorEnv
	o.termWidth = termWidth()

	// Set up follow writer.
	var followWriter io.Writer
	var followFile *os.File
	if o.followOutput != "" {
		f, err := os.Create(o.followOutput)
		if err != nil {
			return err
		}
		followFile = f
		followWriter = f
		defer f.Close()
	} else if o.follow {
		followWriter = os.Stdout
	}
	_ = followFile

	// Determine input.
	var input io.Reader
	var inputFile *os.File
	if o.file != "" {
		f, err := os.Open(o.file)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		inputFile = f
		defer f.Close()
		input = f
	} else {
		fi, _ := os.Stdin.Stat()
		if fi == nil || (fi.Mode()&os.ModeNamedPipe) == 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(1)
		}
		input = os.Stdin
	}
	_ = inputFile

	parser := parse.NewParser()
	hooks := &parse.Hooks{}
	if followWriter != nil {
		hooks.OnEvent = func(e parse.Event) {
			writeFollow(followWriter, e, o.includeTimestamp)
		}
	}
	if o.progress {
		hooks.OnPackageDone = func(e parse.Event, pkg *parse.Package) {
			status := strings.ToUpper(string(e.Action))
			suffix := ""
			if pkg != nil && pkg.NoTestReason != "" {
				status = "SKIP"
				suffix = " " + pkg.NoTestReason
			}
			elapsedStr := fmt.Sprintf("%.2fs", e.Elapsed)
			fmt.Fprintf(os.Stdout, "[%s]\t%10s\t%s%s\n", o.formatStatus(status), elapsedStr, e.Package, suffix)
		}
	}
	if err := parser.Parse(input, hooks); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	pkgs := sortedPackages(parser, o.sortBy)

	o.printTestTables(os.Stdout, pkgs)
	o.printFailuresAndPanics(os.Stdout, pkgs)

	// Compare handling: load (for cover deltas) before summary,
	// but print any warning after the summary.
	var comparePkgs map[string]*parse.Package
	compareLoaded := false
	compareWarning := ""
	if o.compare != "" {
		cp, warning, ok := loadCompare(o.compare)
		if ok {
			comparePkgs = cp
			compareLoaded = true
		} else {
			compareWarning = warning
		}
	}
	o.printSummary(os.Stdout, pkgs, comparePkgs, compareLoaded)
	if compareWarning != "" {
		fmt.Fprintln(os.Stderr, compareWarning)
	}

	for _, pkg := range pkgs {
		if pkg.Panicked || pkg.Action == parse.ActionFail {
			os.Exit(1)
		}
	}
	return nil
}

func loadCompare(path string) (map[string]*parse.Package, string, bool) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Sprintf("warning: failed to open against file: %s", path), false
	}
	defer f.Close()
	p := parse.NewParser()
	if err := p.Parse(f, nil); err != nil {
		return nil, fmt.Sprintf("warning: failed to parse against file: %s", path), false
	}
	return p.Packages, "", true
}

func writeFollow(w io.Writer, e parse.Event, includeTimestamp bool) {
	out := e.Output
	if out == "" {
		return
	}
	trimmed := strings.TrimSpace(out)
	// Skip RUN/PAUSE/CONT and PASS/SKIP result lines.
	if strings.HasPrefix(trimmed, "=== RUN   ") || strings.HasPrefix(trimmed, "=== PAUSE ") || strings.HasPrefix(trimmed, "=== CONT  ") {
		return
	}
	if strings.HasPrefix(trimmed, "--- PASS: ") || strings.HasPrefix(trimmed, "--- SKIP: ") {
		return
	}
	if e.Test == "" && (trimmed == "PASS" || trimmed == "FAIL") {
		return
	}
	if includeTimestamp {
		fmt.Fprintf(w, "%s %s", e.Time.Format(time.RFC3339), out)
	} else {
		fmt.Fprint(w, out)
	}
}

